"""Build-time loader for the audited TRI score integration release.

The decompressed source adds Ranking/Ranking Geral import, stores the official
TRI scores beside each simulation and presents them separately from TCT/acertos.
"""
import base64
import zlib

_SOURCE = ""

exec(compile(zlib.decompress(base64.b64decode(_SOURCE)).decode("utf-8"), __file__, "exec"))
